const express = require('express');
const { execFile } = require('child_process');
const { ScanJob } = require('../models/scanJob');

const app = express();

app.get('/api/compliance/scans/:scanId/report', async (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate scan ownership before executing scanner binary
  const scan = await ScanJob.findOne({
    where: {
      id: req.params.scanId,
      organizationId: req.user.organizationId
    }
  });

  if (!scan) {
    return res.status(404).json({ error: 'Scan job not found or unauthorized' });
  }

  execFile(
    '/opt/scanners/compliance-runner',
    ['--scan-id', req.params.scanId, '--format', 'json'],
    (error, stdout, stderr) => {
      if (error) {
        return res.status(500).json({ error: 'Scanner runner error' });
      }
      res.setHeader('Content-Type', 'application/json');
      res.send(stdout);
    }
  );
});

app.listen(4042);
